from fastapi import FastAPI
from pydantic import BaseModel
app = FastAPI()

class Item(BaseModel):
    name: str
    quantity: int
    price: float

    model_config = {"extra": "forbid"}

    @property
    def total(self) -> float:
        return round(self.quantity * self.price, 2)

    @classmethod
    def __get_pydantic_core_schema__(cls, core_schema, handler):
        def validate(value):
            if not isinstance(value, dict):
                raise ValueError("Item must be a dict")
            name = value.get("name")
            if not isinstance(name, str) or not name.strip():
                raise ValueError("name must be a nonempty string")
            quantity = value.get("quantity")
            if not isinstance(quantity, int) or isinstance(quantity, bool):
                raise ValueError("quantity must be an integer")
            price = value.get("price")
            if not isinstance(price, (int, float)) or isinstance(price, bool):
                raise ValueError("price must be a number")
            value["quantity"] = quantity
            value["price"] = float(price)
            return value

        from pydantic import core_schema
        return core_schema.no_info_plain_validator_schema(cls(validate))

@app.post("/items", status_code=201)
def create_item(item: Item):
    return {"name": item.name, "total": item.total}

